fn fixture_state(name: &str) -> Arc<ServiceState> {
    let fixture = crate::testkit::manifest_dir()
        .join("tests/fixtures")
        .join(name);
    let identity: serde_json::Value =
        serde_json::from_slice(&std::fs::read(fixture.join("identity.json")).unwrap()).unwrap();
    // Public Anvil account #5, fixed by the captured native fixture.
    let attester = crate::attest::Attester::new(
        b256!("8b3a350cf5c34c9194ca85829a2df0ec3153be0318b5e2d3348e872092edffba"),
        identity["vkey"].as_str().unwrap().parse().unwrap(),
        identity["proof_system"].as_str().unwrap().parse().unwrap(),
        eez_primitives::SYSTEM_ADDRESS,
    )
    .unwrap();
    Arc::new(
        ServiceState::new(
            identity["registry_address"]
                .as_str()
                .unwrap()
                .parse()
                .unwrap(),
            identity["rollup_manager_address"]
                .as_str()
                .unwrap()
                .parse()
                .unwrap(),
            Validator::stateless(
                &fixture.join("l2-genesis.json"),
                eez_primitives::SYSTEM_ADDRESS,
            )
            .unwrap(),
            NonZeroU64::new(identity["rollup_id"].as_u64().unwrap()).unwrap(),
            attester,
            Arc::new(reth_chainspec::ChainSpec::from(
                serde_json::from_slice::<alloy_genesis::Genesis>(
                    &std::fs::read(fixture.join("l1-genesis.json")).unwrap(),
                )
                .unwrap(),
            )),
        )
        .unwrap(),
    )
}

fn vector_service(name: &str) -> (serde_json::Value, ProveSvc) {
    let root = crate::testkit::manifest_dir().join("tests/fixtures");
    let vector: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join("streaming-v2").join(format!("{name}.json"))).unwrap(),
    )
    .unwrap();
    let state = fixture_state(vector["fixture"].as_str().unwrap());
    let profile = &vector["server_profile"];
    let nz = |key: &str| NonZeroUsize::new(profile[key].as_u64().unwrap() as usize).unwrap();
    let limits = ServiceLimits::new(ServiceLimitsParams {
        max_window_blocks: nz("max_window_blocks"),
        max_window_bytes: nz("max_window_bytes"),
        max_window_witness_items: nz("max_window_witness_items"),
        stream_idle_timeout: Duration::from_secs(
            profile["stream_idle_timeout_secs"].as_u64().unwrap(),
        ),
        request_timeout: Duration::from_secs(profile["request_timeout_secs"].as_u64().unwrap()),
    })
    .unwrap();
    (vector, ProveSvc::new(state, limits))
}

async fn vector(name: &str) {
    let (vector, service) = vector_service(name);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let endpoint = format!("http://{}", listener.local_addr().unwrap());
    let server_service = service.clone();
    let (stop, shutdown) = tokio::sync::oneshot::channel();
    let server = tokio::spawn(async move {
        tonic::transport::Server::builder()
            .add_service(server_service.into_server())
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown.await;
            })
            .await
            .unwrap();
    });
    let result = timeout(
        Duration::from_secs(90),
        replay::replay(&vector, &endpoint, service.state.validation_identity),
    )
    .await;
    stop.send(()).unwrap();
    server.await.unwrap();
    service.wait_until_idle().await;
    result
        .unwrap()
        .unwrap_or_else(|error| panic!("{name}: {error}"));
    assert_eq!(
        service.state.attester.signing_calls() as u64,
        vector["expected_proofs"].as_u64().unwrap()
    );
}

