#[tokio::test]
async fn finalize_deadline_preserves_prefix_and_allows_retry_in_the_same_epoch() {
    let (vector, fixture) = vector_service("sync-range-proof");
    let service = ProveSvc::new(Arc::clone(&fixture.state), fixture.limits);
    let runtime = &service.sessions;
    let mut bound: Option<BoundSession> = None;
    let mut finalize = None;
    for event in vector["events"].as_array().unwrap() {
        if event["direction"] != "client" {
            continue;
        }
        let mut frame = ClientFrame::decode(
            hex::decode(event["protobuf_hex"].as_str().unwrap())
                .unwrap()
                .as_slice(),
        )
        .unwrap();
        if let Some(binding) = bound {
            frame.session_id = binding.id.to_vec();
            frame.epoch = binding.epoch;
        }
        if matches!(frame.kind, Some(client_frame::Kind::Finalize(_))) {
            finalize = Some(frame);
            // The vector first rejects an incomplete Sync range, then proves
            // the complete range. Exercise the deadline with that valid request.
            continue;
        }
        runtime.handle_frame(&mut bound, frame).await.unwrap();
    }
    let frame = finalize.expect("fixture must exercise Finalize");
    let binding = bound.unwrap();
    let retained = runtime.session(binding.id).await.unwrap();
    let tip = retained.lock().await.tip();
    let occupied = Arc::clone(&service.active_request_slot)
        .acquire_owned()
        .await
        .unwrap();
    // Only admission is waiting: no blocking worker exists while the permit
    // is held. Advance its timer deterministically, then restore real time for
    // the retry's actual replay instead of requiring it to finish in one second.
    tokio::time::pause();
    let (_, error) = runtime
        .handle_frame(&mut bound, frame.clone())
        .await
        .unwrap_err();
    assert_eq!(error.code(), tonic::Code::DeadlineExceeded);
    assert_eq!(error.message(), "Finalize admission deadline exceeded");
    assert_eq!(bound, Some(binding));
    assert_eq!(retained.lock().await.tip(), tip);
    assert_eq!(service.state.attester.signing_calls(), 0);
    tokio::time::resume();
    drop(occupied);
    // Retry without Resume/Rewind: a failed attempt cannot poison its attachment.
    let (response, closed) = runtime.handle_frame(&mut bound, frame).await.unwrap();
    assert!(closed);
    let Some(server_frame::Kind::Proof(proof)) = response.kind else {
        panic!("same-epoch retry did not return Proof");
    };
    assert_eq!(proof.proof.len(), 65);
    assert_eq!(service.state.attester.signing_calls(), 1);
    assert_eq!(bound, Some(binding));
    service.wait_until_idle().await;
}

#[test]
fn wire_replayer_rejects_corrupted_cursor_binding_root_digest_and_attester_oracles() {
    let vector: serde_json::Value = serde_json::from_slice(
        &std::fs::read(
            crate::testkit::manifest_dir().join("tests/fixtures/streaming-v2/baseline-lookup.json"),
        )
        .unwrap(),
    )
    .unwrap();
    let attester = vector["oracle"]["attester"]
        .as_str()
        .unwrap()
        .parse()
        .unwrap();
    for defect in [
        "cursor",
        "request ID",
        "state root",
        "proof digest",
        "attester",
    ] {
        let mut bindings = replay::Bindings::default();
        let mut exercised = false;
        for row in vector["events"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|row| row["direction"] == "server")
        {
            let actual = ServerFrame::decode(
                hex::decode(row["protobuf_hex"].as_str().unwrap())
                    .unwrap()
                    .as_slice(),
            )
            .unwrap();
            let mut expected = actual.clone();
            let mut expected_attester = attester;
            let changed = match (defect, expected.kind.as_mut().unwrap()) {
                ("cursor", server_frame::Kind::Ready(ready)) => {
                    ready.validated_through += 1;
                    true
                }
                ("request ID", server_frame::Kind::Validated(_)) => {
                    expected.request_id += 1;
                    true
                }
                ("state root", server_frame::Kind::Validated(v)) => {
                    v.post_state_root[0] ^= 1;
                    true
                }
                ("proof digest", server_frame::Kind::Proof(p)) => {
                    p.public_inputs_hash[0] ^= 1;
                    true
                }
                ("attester", server_frame::Kind::Proof(_)) => {
                    expected_attester = alloy_primitives::Address::ZERO;
                    true
                }
                _ => false,
            };
            let result = bindings.response(&expected, actual, expected_attester);
            if changed {
                let error = result.unwrap_err().to_string();
                assert!(
                    error.contains("response differs") || error.contains("proof does not recover"),
                    "{defect}: {error}"
                );
                exercised = true;
                break;
            }
            result.unwrap();
        }
        assert!(exercised, "missing oracle mutation: {defect}");
    }
}

struct Controlled {
    service: ProveSvc,
    begin: eez_control_rpc::v2::Begin,
    block: eez_control_rpc::v2::Block,
    started: tokio::sync::oneshot::Receiver<()>,
    release: std::sync::mpsc::Sender<()>,
}
fn controlled(request_timeout: Duration) -> Controlled {
    let parent = crate::testkit::controlled_genesis_header();
    let block = eez_primitives::Block::new(
        alloy_consensus::Header {
            number: 1,
            parent_hash: parent.hash_slow(),
            timestamp: parent.timestamp + 2,
            ..Default::default()
        },
        Default::default(),
    );
    let wire = eez_control_rpc::v2::BlockWitness {
        number: 1,
        hash: block.header.hash_slow().to_vec(),
        parent_hash: parent.hash_slow().to_vec(),
        rlp: alloy_rlp::encode(block),
        witness: Some(eez_control_rpc::v2::ExecutionWitness {
            headers: vec![alloy_rlp::encode(&parent)],
            l1_headers_rlp: vec![alloy_rlp::encode(crate::testkit::controlled_l1_header())],
            ..Default::default()
        }),
    };
    let limits = ServiceLimits::new(ServiceLimitsParams {
        max_window_blocks: NonZeroUsize::new(10).unwrap(),
        max_window_bytes: NonZeroUsize::new(1024 * 1024).unwrap(),
        max_window_witness_items: NonZeroUsize::new(1000).unwrap(),
        stream_idle_timeout: Duration::from_secs(5),
        request_timeout,
    })
    .unwrap();
    let admitted = AdmittedBlock::from_wire(wire.clone(), &mut 0, limits.window_limits()).unwrap();
    let mut output = crate::validate::testing::backend_output_for(&[admitted]);
    // The generic stub uses zero roots. This session's real decoded headers
    // use the empty-trie root, so supply a consistent successful execution.
    output.pre_state_root = parent.state_root;
    output.blocks[0].post_state_root = parent.state_root;
    let (validator, started, release) = Validator::blocking_stub(Ok(output));
    let attester = crate::attest::Attester::new(
        b256!("8b3a350cf5c34c9194ca85829a2df0ec3153be0318b5e2d3348e872092edffba"),
        crate::testkit::test_proof_system_vkey(),
        alloy_primitives::Address::repeat_byte(0xaa),
        eez_primitives::SYSTEM_ADDRESS,
    )
    .unwrap();
    let state = Arc::new(
        ServiceState::new(
            alloy_primitives::Address::repeat_byte(0x33),
            alloy_primitives::Address::repeat_byte(0x44),
            validator,
            NonZeroU64::new(1).unwrap(),
            attester,
            crate::testkit::l1_chain_spec(),
        )
        .unwrap(),
    );
    Controlled {
        service: ProveSvc::new(state, limits),
        begin: eez_control_rpc::v2::Begin {
            rollup_id: 1,
            anchor_number: 0,
            anchor_hash: parent.hash_slow().to_vec(),
            anchor_state_root: parent.state_root.to_vec(),
        },
        block: eez_control_rpc::v2::Block { data: Some(wire) },
        started,
        release,
    }
}

async fn open_controlled(
    fixture: &Controlled,
) -> (
    tokio::task::JoinHandle<()>,
    mpsc::Sender<ClientFrame>,
    Streaming<ServerFrame>,
    ServerFrame,
) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let endpoint = format!("http://{}", listener.local_addr().unwrap());
    let service = fixture.service.clone();
    let server = tokio::spawn(async move {
        tonic::transport::Server::builder()
            .add_service(service.clone().into_server())
            .serve_with_incoming(TcpListenerStream::new(listener))
            .await
            .unwrap();
    });
    let mut client = eez_control_rpc::v2::prover_client::ProverClient::connect(endpoint)
        .await
        .unwrap();
    let (tx, rx) = mpsc::channel(8);
    let mut request = tonic::Request::new(ReceiverStream::new(rx));
    request.metadata_mut().insert_bin(
        "eez-validation-identity-bin",
        tonic::metadata::MetadataValue::from_bytes(
            fixture.service.state.validation_identity.as_slice(),
        ),
    );
    let mut response = client.prove_stream(request).await.unwrap().into_inner();
    tx.send(ClientFrame {
        request_id: 1,
        kind: Some(client_frame::Kind::Begin(fixture.begin.clone())),
        ..Default::default()
    })
    .await
    .unwrap();
    let ready = response.message().await.unwrap().unwrap();
    assert!(matches!(ready.kind, Some(server_frame::Kind::Ready(_))));
    (server, tx, response, ready)
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn queued_work_is_bounded_by_count_bytes_and_witness_items_before_execution() {
    for quota in ["count", "bytes", "items"] {
        let mut fixture = controlled(Duration::from_secs(5));
        fixture.service = ProveSvc::new(
            Arc::clone(&fixture.service.state),
            ServiceLimits::new(ServiceLimitsParams {
                max_window_blocks: NonZeroUsize::new(if quota == "count" { 1 } else { 10 })
                    .unwrap(),
                max_window_bytes: NonZeroUsize::new(4096).unwrap(),
                max_window_witness_items: NonZeroUsize::new(if quota == "items" { 2 } else { 100 })
                    .unwrap(),
                stream_idle_timeout: Duration::from_secs(5),
                request_timeout: Duration::from_secs(5),
            })
            .unwrap(),
        );
        let (server, tx, mut response, ready) = open_controlled(&fixture).await;
        let mut frame = ClientFrame {
            session_id: ready.session_id,
            epoch: ready.epoch,
            request_id: 2,
            kind: Some(client_frame::Kind::Block(fixture.block)),
        };
        tx.send(frame.clone()).await.unwrap();
        fixture.started.await.unwrap();
        let Some(client_frame::Kind::Block(block)) = frame.kind.as_mut() else {
            unreachable!()
        };
        if quota == "bytes" {
            block
                .data
                .as_mut()
                .unwrap()
                .witness
                .as_mut()
                .unwrap()
                .codes
                .push(vec![0; 2300]);
        } else if quota == "items" {
            block
                .data
                .as_mut()
                .unwrap()
                .witness
                .as_mut()
                .unwrap()
                .codes
                .push(vec![]);
        }
        for id in 3..=6 {
            frame.request_id = id;
            if tx.send(frame.clone()).await.is_err() {
                break;
            }
        }
        let error = timeout(Duration::from_secs(2), response.message())
            .await
            .unwrap()
            .unwrap_err();
        assert_eq!(error.code(), tonic::Code::ResourceExhausted, "{quota}");
        assert_eq!(
            error.message(),
            "ProveStream pending request quota exceeded"
        );
        assert_eq!(fixture.service.validation_worker.available_permits(), 0);
        fixture.release.send(()).unwrap();
        fixture.service.wait_until_idle().await;
        let retained = fixture
            .service
            .sessions
            .session(B256::from_slice(&frame.session_id))
            .await
            .unwrap();
        assert_eq!(
            retained.lock().await.tip().number,
            0,
            "{quota}: cancelled operation advanced cursor"
        );
        assert_eq!(fixture.service.state.attester.signing_calls(), 0);
        server.abort();
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn rejected_rewind_keeps_the_running_and_queued_duplicate_blocks() {
    let fixture = controlled(Duration::from_secs(5));
    let (server, tx, mut response, ready) = open_controlled(&fixture).await;
    let mut frame = ClientFrame {
        session_id: ready.session_id,
        epoch: ready.epoch,
        request_id: 2,
        kind: Some(client_frame::Kind::Block(fixture.block)),
    };
    tx.send(frame.clone()).await.unwrap();
    fixture.started.await.unwrap();
    frame.request_id = 3;
    tx.send(frame.clone()).await.unwrap();
    frame.request_id = 4;
    frame.kind = Some(client_frame::Kind::Rewind(eez_control_rpc::v2::Rewind {
        ancestor_hash: vec![0xff; 32],
    }));
    tx.send(frame).await.unwrap();
    let rejected = timeout(Duration::from_secs(2), response.message())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(rejected.request_id, 4);
    assert!(matches!(
        rejected.kind,
        Some(server_frame::Kind::Rejected(Rejected { code: 9, .. }))
    ));
    fixture.release.send(()).unwrap();
    drop(tx); // Half-close must drain both admitted blocks.
    for (id, reused) in [(2, false), (3, true)] {
        let actual = timeout(Duration::from_secs(2), response.message())
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(actual.request_id, id);
        assert!(
            matches!(&actual.kind, Some(server_frame::Kind::Validated(v)) if v.reused == reused && v.number == 1),
            "unexpected block response: {actual:?}"
        );
    }
    assert!(response.message().await.unwrap().is_none());
    fixture.service.wait_until_idle().await;
    server.abort();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn resume_rewind_and_cancel_fence_running_validation_without_releasing_its_worker() {
    for operation in ["resume", "rewind", "cancel"] {
        let fixture = controlled(Duration::from_secs(5));
        let runtime = Arc::clone(&fixture.service.sessions);
        let (bound, _) = runtime.begin(fixture.begin.clone(), 74).await.unwrap();
        let (peer, _) = runtime.begin(fixture.begin.clone(), 74).await.unwrap();
        let task_runtime = Arc::clone(&runtime);
        let work = tokio::spawn(async move {
            task_runtime
                .validate_block(bound, fixture.block, 1000)
                .await
        });
        fixture.started.await.unwrap();
        match operation {
            "resume" => {
                runtime.resume(bound.id).await.unwrap();
            }
            "rewind" => {
                runtime
                    .rewind(bound, B256::from_slice(&fixture.begin.anchor_hash))
                    .await
                    .unwrap();
            }
            "cancel" => {
                runtime
                    .handle_frame(
                        &mut Some(bound),
                        ClientFrame {
                            session_id: bound.id.to_vec(),
                            epoch: bound.epoch,
                            request_id: 2,
                            kind: Some(client_frame::Kind::Cancel(Default::default())),
                        },
                    )
                    .await
                    .unwrap();
            }
            _ => unreachable!(),
        }
        assert_eq!(fixture.service.validation_worker.available_permits(), 0);
        fixture.release.send(()).unwrap();
        assert_eq!(
            work.await.unwrap().unwrap_err().code(),
            tonic::Code::Cancelled,
            "{operation} must fence otherwise valid execution"
        );
        assert_eq!(fixture.service.state.attester.signing_calls(), 0);
        let peer = runtime.session(peer.id).await.unwrap();
        assert_eq!(peer.lock().await.tip().number, 0);
        if operation != "cancel" {
            let retained = runtime.session(bound.id).await.unwrap();
            assert_eq!(retained.lock().await.tip().number, 0);
        }
        fixture.service.wait_until_idle().await;
        assert_eq!(fixture.service.validation_worker.available_permits(), 1);
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn active_block_uses_its_request_deadline_instead_of_the_input_idle_timeout() {
    let mut fixture = controlled(Duration::from_secs(5));
    fixture.service = ProveSvc::new(
        Arc::clone(&fixture.service.state),
        ServiceLimits {
            stream_idle_timeout: Duration::from_millis(100),
            ..fixture.service.limits
        },
    );
    let (server, tx, mut response, ready) = open_controlled(&fixture).await;
    tx.send(ClientFrame {
        session_id: ready.session_id,
        epoch: ready.epoch,
        request_id: 2,
        kind: Some(client_frame::Kind::Block(fixture.block)),
    })
    .await
    .unwrap();
    fixture.started.await.unwrap();
    assert!(
        timeout(Duration::from_millis(250), response.message())
            .await
            .is_err(),
        "active execution was interrupted by the shorter input idle timeout"
    );
    fixture.release.send(()).unwrap();
    let response = response.message().await.unwrap().unwrap();
    assert!(matches!(response.kind, Some(server_frame::Kind::Validated(v)) if v.number == 1));
    drop(tx);
    fixture.service.wait_until_idle().await;
    server.abort();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn timed_out_stream_block_keeps_worker_and_never_advances_cursor() {
    let fixture = controlled(Duration::from_millis(50));
    let runtime = Arc::clone(&fixture.service.sessions);
    let (bound, _) = runtime.begin(fixture.begin, 74).await.unwrap();
    let task_runtime = Arc::clone(&runtime);
    let work = tokio::spawn(async move {
        task_runtime
            .validate_block(bound, fixture.block, 1000)
            .await
    });
    fixture.started.await.unwrap();
    assert_eq!(
        work.await.unwrap().unwrap_err().code(),
        tonic::Code::DeadlineExceeded
    );
    assert_eq!(fixture.service.validation_worker.available_permits(), 0);
    let waiter = fixture.service.clone();
    let shutdown = tokio::spawn(async move {
        waiter.wait_until_idle().await;
    });
    tokio::task::yield_now().await;
    assert!(!shutdown.is_finished());
    fixture.release.send(()).unwrap();
    timeout(Duration::from_secs(2), shutdown)
        .await
        .unwrap()
        .unwrap();
    assert_eq!(
        runtime
            .session(bound.id)
            .await
            .unwrap()
            .lock()
            .await
            .tip()
            .number,
        0
    );
    assert_eq!(fixture.service.state.attester.signing_calls(), 0);
}

#[tokio::test]
async fn panicking_stream_worker_returns_redacted_error_without_progress_or_signature() {
    let mut fixture = controlled(Duration::from_secs(5));
    let attester = crate::attest::Attester::new(
        b256!("8b3a350cf5c34c9194ca85829a2df0ec3153be0318b5e2d3348e872092edffba"),
        crate::testkit::test_proof_system_vkey(),
        alloy_primitives::Address::repeat_byte(0xaa),
        eez_primitives::SYSTEM_ADDRESS,
    )
    .unwrap();
    let state = Arc::new(
        ServiceState::new(
            alloy_primitives::Address::repeat_byte(0x33),
            alloy_primitives::Address::repeat_byte(0x44),
            Validator::panicking_stub(),
            NonZeroU64::new(1).unwrap(),
            attester,
            crate::testkit::l1_chain_spec(),
        )
        .unwrap(),
    );
    fixture.service = ProveSvc::new(state, fixture.service.limits);
    let (server, tx, mut responses, ready) = open_controlled(&fixture).await;
    tx.send(ClientFrame {
        session_id: ready.session_id,
        epoch: ready.epoch,
        request_id: 2,
        kind: Some(client_frame::Kind::Block(fixture.block)),
    })
    .await
    .unwrap();
    let response = responses.message().await.unwrap().unwrap();
    let Some(server_frame::Kind::Rejected(error)) = response.kind else {
        panic!("worker panic must reject")
    };
    assert_eq!(error.code, tonic::Code::Internal as i32);
    assert_eq!(error.message, "block validation worker failed");
    assert_eq!(error.validated_through, 0);
    assert!(error.details.is_empty());
    assert_eq!(fixture.service.state.attester.signing_calls(), 0);
    drop(tx);
    fixture.service.wait_until_idle().await;
    assert_eq!(fixture.service.validation_worker.available_permits(), 1);
    server.abort();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn shutdown_closes_live_rpc_but_waits_for_detached_execution() {
    let fixture = controlled(Duration::from_secs(30));
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let endpoint = format!("http://{}", listener.local_addr().unwrap());
    let service = fixture.service.clone();
    let (stop, shutdown) = tokio::sync::oneshot::channel();
    let server = tokio::spawn(async move {
        tonic::transport::Server::builder()
            .add_service(service.clone().into_server())
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown.await;
                service.stop_streams();
            })
            .await
            .unwrap();
        service.wait_until_idle().await;
    });
    let mut client = eez_control_rpc::v2::prover_client::ProverClient::connect(endpoint)
        .await
        .unwrap();
    let (tx, rx) = mpsc::channel(8);
    let mut request = tonic::Request::new(ReceiverStream::new(rx));
    request.metadata_mut().insert_bin(
        "eez-validation-identity-bin",
        tonic::metadata::MetadataValue::from_bytes(
            fixture.service.state.validation_identity.as_slice(),
        ),
    );
    let mut response = client.prove_stream(request).await.unwrap().into_inner();
    tx.send(ClientFrame {
        request_id: 1,
        kind: Some(client_frame::Kind::Begin(fixture.begin)),
        ..Default::default()
    })
    .await
    .unwrap();
    let ready = response.message().await.unwrap().unwrap();
    assert!(matches!(ready.kind, Some(server_frame::Kind::Ready(_))));
    let id = B256::from_slice(&ready.session_id);
    tx.send(ClientFrame {
        session_id: ready.session_id,
        epoch: ready.epoch,
        request_id: 2,
        kind: Some(client_frame::Kind::Block(fixture.block)),
    })
    .await
    .unwrap();
    fixture.started.await.unwrap();
    stop.send(()).unwrap();
    assert!(
        timeout(Duration::from_secs(2), response.message())
            .await
            .unwrap()
            .unwrap()
            .is_none()
    );
    drop(tx);
    drop(client);
    assert_eq!(fixture.service.validation_worker.available_permits(), 0);
    assert!(!server.is_finished());
    fixture.release.send(()).unwrap();
    timeout(Duration::from_secs(2), server)
        .await
        .unwrap()
        .unwrap();
    assert_eq!(fixture.service.state.attester.signing_calls(), 0);
    assert_eq!(
        fixture
            .service
            .sessions
            .session(id)
            .await
            .unwrap()
            .lock()
            .await
            .tip()
            .number,
        0
    );
}

#[tokio::test]
async fn backpressured_publication_rechecks_epoch_and_shutdown_interrupts_output() {
    let fixture = controlled(Duration::from_secs(5));
    let runtime = Arc::clone(&fixture.service.sessions);
    let (bound, ready) = runtime.begin(fixture.begin, 74).await.unwrap();
    let (tx, mut rx) = mpsc::channel(1);
    tx.send(Ok(server_frame(bound, 1, server_frame::Kind::Ready(ready))))
        .await
        .unwrap();
    let task_runtime = Arc::clone(&runtime);
    let task_tx = tx.clone();
    let pending = tokio::spawn(async move {
        task_runtime
            .send_response(
                &task_tx,
                Ok(server_frame(
                    bound,
                    2,
                    server_frame::Kind::Validated(Validated::default()),
                )),
            )
            .await
    });
    tokio::task::yield_now().await;
    assert!(!pending.is_finished());
    runtime.resume(bound.id).await.unwrap();
    rx.recv().await.unwrap().unwrap();
    assert!(!pending.await.unwrap());
    assert!(rx.try_recv().is_err());

    tx.send(Err(Status::cancelled("fill output")))
        .await
        .unwrap();
    let task_runtime = Arc::clone(&runtime);
    let pending = tokio::spawn(async move {
        task_runtime
            .send_response(&tx, Err(Status::cancelled("blocked output")))
            .await
    });
    tokio::task::yield_now().await;
    assert!(!pending.is_finished());
    fixture.service.stop_streams();
    assert!(
        !timeout(Duration::from_secs(1), pending)
            .await
            .unwrap()
            .unwrap()
    );
}

#[tokio::test]
async fn exhausted_epoch_rejects_controls_without_mutating_session() {
    let fixture = controlled(Duration::from_secs(5));
    let runtime = &fixture.service.sessions;
    let (mut bound, _) = runtime.begin(fixture.begin, 74).await.unwrap();
    bound.epoch = u64::MAX;
    let retained = runtime.session(bound.id).await.unwrap();
    retained.lock().await.epoch = bound.epoch;
    assert_eq!(
        runtime.resume(bound.id).await.unwrap_err().code(),
        tonic::Code::ResourceExhausted
    );
    let anchor = retained.lock().await.anchor.hash;
    assert_eq!(
        runtime.rewind(bound, anchor).await.unwrap_err().code(),
        tonic::Code::ResourceExhausted
    );
    let retained = retained.lock().await;
    assert_eq!(retained.epoch, u64::MAX);
    assert!(!retained.cancellation.is_cancelled());
}

#[tokio::test]
async fn incompatible_validation_identity_is_rejected_before_session_creation() {
    let fixture = controlled(Duration::from_secs(5));
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let endpoint = format!("http://{}", listener.local_addr().unwrap());
    let service = fixture.service.clone();
    let server = tokio::spawn(async move {
        tonic::transport::Server::builder()
            .add_service(service.clone().into_server())
            .serve_with_incoming(TcpListenerStream::new(listener))
            .await
            .unwrap();
    });
    let mut client = eez_control_rpc::v2::prover_client::ProverClient::connect(endpoint)
        .await
        .unwrap();
    for identity in [
        None,
        Some(vec![]),
        Some(vec![0; 31]),
        Some(vec![0; 32]),
        Some(vec![0; 33]),
    ] {
        let (_sender, receiver) = mpsc::channel::<ClientFrame>(1);
        let mut request = Request::new(ReceiverStream::new(receiver));
        if let Some(identity) = &identity {
            request.metadata_mut().insert_bin(
                "eez-validation-identity-bin",
                tonic::metadata::MetadataValue::from_bytes(identity),
            );
        }
        let error = timeout(Duration::from_secs(2), client.prove_stream(request))
            .await
            .expect("identity rejection must not wait for a frame or EOF")
            .unwrap_err();
        assert_eq!(error.code(), tonic::Code::FailedPrecondition);
        assert_eq!(
            error.message(),
            if identity.is_none() {
                "offline validation identity metadata is required"
            } else {
                "validation identity mismatch"
            }
        );
        assert!(
            error.details().is_empty(),
            "identity failures cannot evict a source"
        );
        assert_eq!(fixture.service.state.attester.signing_calls(), 0);
    }
    assert!(
        fixture
            .service
            .sessions
            .registry
            .lock()
            .await
            .sessions
            .is_empty()
    );
    assert_eq!(fixture.service.state.attester.signing_calls(), 0);
    server.abort();
}
